/** Whole-query routing must prove both graph membership and coverage of every data dependency. */
public class FedXSingleSourceGraphTest extends SPARQLBaseTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI GRAPH = VF.createIRI("urn:delegation:claims");
	private static final IRI EDGE = VF.createIRI("urn:delegation:edge");
	private static final IRI SUBJECT = VF.createIRI("urn:delegation:subject");
	private static final IRI OBJECT = VF.createIRI("urn:delegation:object");
	private static final IRI SOURCE = VF.createIRI("urn:delegation:source");
	private static final BNode CLAIM = VF.createBNode("delegationClaim");
	private static final TripleTerm TERM = VF.createTripleTerm(SUBJECT, EDGE, OBJECT);
	private static final String TERM_QUERY = "SELECT ?g ?part ?tail ?source WHERE { GRAPH ?g { "
			+ "?claim <" + RDF.REIFIES + "> <<(?part <" + EDGE + "> ?tail)>> ; <" + SOURCE + "> ?source } }";

	@BeforeEach
	public void prepareSinglePopulatedMember() throws Exception {
		prepareTest(List.of("/tests/basic/data_emptyStore.ttl", "/tests/basic/data_emptyStore.ttl"));
		try (RepositoryConnection first = getRepository(1).getConnection()) {
			first.add(CLAIM, RDF.REIFIES, TERM, GRAPH);
			first.add(CLAIM, SOURCE, VF.createLiteral("local source"), GRAPH);
		}
		assertThat(federationContext().getConfig().isEnableTripleRefSupport()).isFalse();
	}

	@Test
	public void completePhysicalCoverageRetainsNativeTripleTermWholeQueryRoute() {
		assertThat(optimize(TERM_QUERY, null)).isInstanceOf(SingleSourceQuery.class);
		assertTermRows(query(TERM_QUERY, null));
	}

	@ParameterizedTest
	@ValueSource(strings = { "default", "named" })
	public void nativeStoredObjectKeepsExactRowsWithUnrelatedMembers(String dataLocation) {
		try (RepositoryConnection second = getRepository(2).getConnection()) {
			IRI resource = VF.createIRI("urn:delegation:otherResource");
			if (dataLocation.equals("named")) {
				second.add(resource, EDGE, VF.createLiteral("unrelated"), VF.createIRI("urn:delegation:otherGraph"));
			} else {
				second.add(resource, EDGE, VF.createLiteral("unrelated"));
			}
		}
		assertThat(optimize(TERM_QUERY, null)).isInstanceOf(SingleSourceQuery.class);
		assertTermRows(query(TERM_QUERY, null));
	}

	@ParameterizedTest
	@ValueSource(strings = { "default", "named", "split-default", "split-named" })
	public void encodedResourceRepresentationOnAnotherMemberBlocksColocationProof(String placement) {
		IRI encoded = VF.createIRI("urn:delegation:encodedTerm");
		IRI representationGraph = VF.createIRI("urn:delegation:representationGraph");
		Resource[] contexts = placement.endsWith("named")
				? new Resource[] { representationGraph }
				: new Resource[] { null };
		try (RepositoryConnection first = getRepository(1).getConnection();
				RepositoryConnection second = getRepository(2).getConnection()) {
			first.remove(CLAIM, RDF.REIFIES, TERM, GRAPH);
			first.add(CLAIM, RDF.REIFIES, encoded, GRAPH);
			if (placement.startsWith("split")) {
				first.add(encoded, RDF.TYPE, RDF.PROPOSITION_FORM, GRAPH);
			} else {
				second.add(encoded, RDF.TYPE, RDF.PROPOSITION_FORM, contexts);
			}
			second.add(encoded, RDF.PROPOSITION_FORM_SUBJECT, SUBJECT, contexts);
			second.add(encoded, RDF.PROPOSITION_FORM_PREDICATE, EDGE, contexts);
			second.add(encoded, RDF.PROPOSITION_FORM_OBJECT, OBJECT, contexts);
		}
		assertThat(optimize(TERM_QUERY, null)).isNotInstanceOf(SingleSourceQuery.class);
	}

	@Test
	public void coveredExtensionDoesNotRequireOtherMembersToBeEmpty() {
		try (RepositoryConnection second = getRepository(2).getConnection()) {
			second.add(OBJECT, EDGE, SUBJECT, VF.createIRI("urn:delegation:unrelatedGraph"));
		}
		String text = "SELECT ?g ?source ?copy WHERE { GRAPH ?g { ?claim <" + SOURCE
				+ "> ?source . BIND(STR(?source) AS ?copy) } }";
		assertThat(optimize(text, null)).isInstanceOf(SingleSourceQuery.class);
		assertThat(query(text, null))
				.extracting(row -> tuple(row.getValue("g"), row.getValue("source"), row.getValue("copy")))
				.containsExactly(tuple(GRAPH, VF.createLiteral("local source"), VF.createLiteral("local source")));
	}

	@Test
	public void endpointRestrictionDefinesTheCoverageUniverse() {
		try (RepositoryConnection second = getRepository(2).getConnection()) {
			second.add(OBJECT, EDGE, SUBJECT, VF.createIRI("urn:delegation:excludedMemberGraph"));
		}
		FedXDataset dataset = new FedXDataset(null);
		dataset.addEndpoint(federationContext().getEndpointManager().getEndpointByName("http://endpoint1").getId());
		assertThat(optimize(TERM_QUERY, dataset)).isInstanceOf(SingleSourceQuery.class);
		assertTermRows(query(TERM_QUERY, dataset));
	}

	@Test
	public void declaredEmptyNestedGraphDoesNotAcquireStatementOrigin() {
		IRI emptyGraph = VF.createIRI("urn:delegation:declaredEmpty");
		SimpleDataset dataset = new SimpleDataset();
		dataset.addNamedGraph(GRAPH);
		dataset.addNamedGraph(emptyGraph);
		String text = "SELECT ?g ?claim ?source WHERE { GRAPH ?g { ?claim <" + SOURCE
				+ "> ?source . GRAPH <" + emptyGraph + "> {} } }";
		assertThat(optimize(text, dataset)).isNotInstanceOf(SingleSourceQuery.class);
		assertThat(query(text, dataset))
				.extracting(row -> tuple(row.getValue("g"), identity(row.getValue("claim")), row.getValue("source")))
				.containsExactly(tuple(GRAPH,
						memberValue(federationContext().getEndpointManager().getEndpointByName("http://endpoint1"),
								CLAIM),
						VF.createLiteral("local source")));
	}

	private TupleExpr optimize(String text, Dataset dataset) {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, text, null);
		var context = federationContext();
		var strategy = context.createStrategy(dataset);
		var queryInfo = new QueryInfo(text, null, QueryType.SELECT, 0, false, context, strategy, dataset);
		return strategy.optimize(parsed.getTupleExpr(), new FederationEvaluationStatistics(queryInfo, dataset),
				EmptyBindingSet.getInstance());
	}

	private List<BindingSet> query(String text, Dataset dataset) {
		try (RepositoryConnection connection = fedxRule.getRepository().getConnection()) {
			var prepared = connection.prepareTupleQuery(text);
			prepared.setDataset(dataset);
			try (var rows = prepared.evaluate()) {
				assertThat(rows.getBindingNames()).containsExactlyInAnyOrderElementsOf(
						QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, text, null)
								.getTupleExpr()
								.getBindingNames());
				return QueryResults.asList(rows);
			}
		}
	}

	private void assertTermRows(List<BindingSet> rows) {
		rows.forEach(row -> assertThat(row.getBindingNames()).containsExactlyInAnyOrder("g", "part", "tail", "source"));
		assertThat(rows).extracting(
				row -> tuple(row.getValue("g"), row.getValue("part"), row.getValue("tail"), row.getValue("source")))
				.containsExactly(tuple(GRAPH, SUBJECT, OBJECT, VF.createLiteral("local source")));
	}
}
